import type { GlideRecord } from '../../script/GlideRecord'
import type { Column, Typed } from '../Column'
import type { TableName } from '../Table'

/**
 * The dropdown values are mapped to the following values on the platform
 *
 * - `none`: 0
 * - `dropdown_with_none`: 1
 * - `suggestion`: 2
 * - `dropdown_without_none`: 3
 *
 */
export const choiceDropdown = ['none', 'dropdown_with_none', 'suggestion', 'dropdown_without_none'] as const

export type choiceDropdownType = (typeof choiceDropdown)[number]

/**
 * Construct a type that accepts any string but also a list of suggestions (Ex. <'suggestion 1' | 'suggestion 2'>)
 */
type StringWithSuggestions<T> = T | ((string | number) & Record<never, never>)

export type SuggestionOrChoiceType<
    D extends choiceDropdownType = 'none',
    TChoices extends Choices = Choices,
> = D extends 'suggestion' ? StringWithSuggestions<keyof TChoices> : ChoiceType<TChoices>

export type Choices<T extends string | number = string | number> = Record<T, ChoiceValue>
type ChoiceValue = string | ChoiceConfig

export type ChoiceConfig = {
    label: string
    sequence?: number
    hint?: string
    inactive?: boolean
    language?: string
} & (
    | {
          dependentValue?: string | number
          inactiveOnUpdate?: boolean
          /** @deprecated Use dependentValue instead */
          dependent_value?: never
          /** @deprecated Use inactiveOnUpdate instead */
          inactive_on_update?: never
      }
    | {
          /** @deprecated Use dependentValue instead */
          dependent_value?: string | number
          /** @deprecated Use inactiveOnUpdate instead */
          inactive_on_update?: boolean
          dependentValue?: never
          inactiveOnUpdate?: never
      }
)

export type ChoiceType<TChoices extends Choices> = keyof TChoices

export type ChoiceColumnType<
    TChoices extends Choices = Choices,
    Type extends SuggestionOrChoiceType<Dropdown, TChoices> = ChoiceType<TChoices>,
    Default extends Type = Type,
    ReferenceSchema extends TableName = TableName,
    Dropdown extends choiceDropdownType = choiceDropdownType,
> = Column<Type, Default> & {
    /** Choice values definitions as object literal: { choice_1: { label: 'Choice1' }, choice_2: { label: 'Choice2' },} */
    choices?: TChoices
    dropdown?: Dropdown | choiceDropdownType
} & (
        | {
              /** Object literal, specify type and then relevant additional parameters for reference choices and script defaults*/
              dynamicValueDefinitions?: DynamicValueDefinitions<ReferenceSchema>
              /** @deprecated use dynamicValueDefinitions instead */
              dynamic_value_definitions?: never
          }
        | {
              /** Object literal, specify type and then relevant additional parameters for reference choices and script defaults*/
              dynamicValueDefinitions?: never
              /** @deprecated use dynamicValueDefinitions instead */
              dynamic_value_definitions?: DynamicValueDefinitions<ReferenceSchema>
          }
    )

/**
 * A Column for a choice type field.
 *
 * @see https://docs.servicenow.com/csh?topicname=table-api-now-ts.html&version=latest
 *
 * @param config - an object that can include all base `Column` properties and the following:
 *   * **choices** - choice value definitions
 *   * **dropdown** - how a list of choices displays for users of your form
 *   * **dynamicValueDefinitions** - default values that are generated dynamically based on dynamic filters
 */
export function ChoiceColumn<
    const TChoices extends Choices,
    const Type extends SuggestionOrChoiceType<Dropdown, TChoices>,
    const Default extends Type,
    const C extends ChoiceColumnType<TChoices, Type, Default, ReferenceSchema>,
    const ReferenceSchema extends TableName,
    const Dropdown extends choiceDropdownType = 'none',
>(config: C & ChoiceColumnType<TChoices, Type, Default, ReferenceSchema, Dropdown>) {
    return config as Typed<Type, C>
}

export type DynamicValueDefinitions<ReferenceSchema extends TableName> =
    | ({
          type: 'calculated_value'
      } & (
          | {
                /** Call an imported modular JS function, current GlideRecord can be provided as an arg */
                calculatedValue: ((current: GlideRecord<ReferenceSchema>) => string) | string
                /** @deprecated Use calculatedValue instead */
                calculated_value?: never
            }
          | {
                /** Call an imported modular JS function, current GlideRecord can be provided as an arg */
                calculatedValue?: never
                /** @deprecated Use calculatedValue instead */
                calculated_value: ((current: GlideRecord<ReferenceSchema>) => string) | string
            }
      ))
    | ({
          /**
           * @deprecated Use the `dependent` property directly on the column instead.
           */
          type: 'dependent_field'
      } & (
          | {
                /** column from this table */
                columnName: string
                /** @deprecated Use columnName instead */
                column_name?: never
            }
          | {
                /** column from this table */
                columnName?: never
                /** @deprecated Use columnName instead */
                column_name: string
            }
      ))
    | {
          type: 'choices_from_other_table'
          /** String table name, escape with `` (import from @servicenow/sdk-core/global) if not locally available */
          table: ReferenceSchema
          /** Field from specified table */
          field: string
      }
